for (const Edge& edge : graph.get_edges(current_node->id)) {
    Node* neighbor = graph.get_node(edge.to);
    if (neighbor->visited) continue;

    double tentative_g = current_node->g + edge.cost;
    bool in_open = false;
    for (Node* node : open_list) {
        if (node->id == neighbor->id) {
            in_open = true;
            if (tentative_g < node->g) {
                node->g = tentative_g;
                node->f = node->g + node->h;
                node->parent = current_node;
            }
            break;
        }
    }

    if (!in_open) {
        neighbor->g = tentative_g;
        neighbor->h = graph.heuristic(neighbor->id, end_node->id);
        neighbor->f = neighbor->g + neighbor->h;
        neighbor->parent = current_node;
        open_list.push_back(neighbor);
    }
}
